<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
const props=defineProps({classroom:String,manager:Boolean}),rows=ref([]),error=ref(''),busy=ref(false),draft=ref({rating:5,body:''})
async function run(fn){error.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){rows.value=await request('workspace','reviews',{classroom:props.classroom},'GET');const own=rows.value.find(x=>x.mine);if(own)draft.value={rating:own.rating,body:own.body}}
async function moderate(row,action){const body=window.prompt(action==='reply'?'Your reply':'Reason for this moderation action');if(body)await run(async()=>{await request('workspace','moderate_review',{name:row.name,action,body});await load()})}
onMounted(()=>run(load))
</script>
<template><section class="class-reviews"><h2>Learning, in your words.</h2><p>Reviews from enrolled learners. One review per learner, with space for a teacher’s reply.</p><p v-if="error" role="alert">{{error}}</p><form v-if="!manager&&!error" @submit.prevent="run(async()=>{await request('workspace','save_review',{classroom,data:draft});await load()})"><label>Your rating<select v-model.number="draft.rating"><option v-for="n in 5" :value="n">{{n}} {{n===1?'star':'stars'}}</option></select></label><label>Your experience<textarea v-model="draft.body" minlength="10" maxlength="1500" required placeholder="What helped you learn?"/></label><button class="button primary" :disabled="busy">Save my review</button></form><article v-for="r in rows" :key="r.name"><div><strong>{{r.student_name}}</strong><span aria-label="Rating">{{'★'.repeat(r.rating)}}{{'☆'.repeat(5-r.rating)}}</span><small v-if="r.status==='Hidden'">Hidden · {{r.moderation_reason}}</small></div><p>{{r.body}}</p><blockquote v-if="r.reply"><strong>Teacher’s reply</strong><p>{{r.reply}}</p></blockquote><div v-if="manager" class="inline"><button class="text-button" @click="moderate(r,'reply')">Reply</button><button class="text-button" @click="moderate(r,r.status==='Hidden'?'restore':'hide')">{{r.status==='Hidden'?'Restore':'Hide with reason'}}</button></div></article><p v-if="!rows.length&&!error">The first learning story starts here.</p></section></template>
<style scoped>.class-reviews>p{color:#796e86}.class-reviews article{padding:23px 0;border-top:1px solid #e8e0f0}.class-reviews article>div{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.class-reviews span{color:#7651a2;letter-spacing:3px}.class-reviews p{line-height:1.8;white-space:pre-wrap}.class-reviews blockquote{margin:15px 0;background:#f5f0fa;border-left:3px solid #a17bcc;padding:16px;border-radius:0 12px 12px 0}.class-reviews form{background:#f7f3fb;padding:22px;border-radius:16px;margin:20px 0}.class-reviews label{display:grid;gap:8px;margin-bottom:15px}.class-reviews textarea{min-height:100px}.class-reviews textarea,.class-reviews select{padding:12px;border:1px solid #dfd3ec;border-radius:10px;font:inherit}</style>
